import {tasks,taskScenes,sources,scenes,quotes,mesotes,lives} from './data/content.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const button=(label,action,extra='')=>`<button type="button" data-action="${action}" ${extra}>${label}</button>`;
const pose=(i,extra='',label='Gezeichnete Erklärfigur')=>`<div class="pose ${extra}" role="img" aria-label="${esc(label)}" style="--pose-x:${i%3*50}%;--pose-y:${i>2?100:0}%"></div>`;
const reveal=(step,html,extra='')=>`<div class="reveal ${extra}" data-reveal="${step}">${html}</div>`;
const tag=s=>s.task?`AUFGABE ${s.task} / 6`:(s.id==='01'?'EINE FRAGE ZUM ANFANG':s.id==='02'?'UNSER WEG DURCH DAS LYKEION':s.id==='13'?'UNSERE SCHLUSSBETRACHTUNG':'QUELLEN & NACHWEISE');
export const cite=(id,detail='',range='')=>button(`${id}${detail?' · '+esc(detail):''}`,'source',`class="citation" data-id="${id}" data-range="${range}" aria-label="Quelle ${id}${detail?' '+esc(detail):''} öffnen"`);
const quote=index=>{const q=quotes[index];return `<blockquote><p>„${esc(q.text)}“</p><footer>${cite('Q1',`S. ${q.page} · Z. ${q.lines.join('–')}`,q.lines.join('-'))}</footer></blockquote>`;};
const caption=text=>`<p class="art-caption">${text}</p>`;
const heading=(s,title=s.title,subtitle='')=>`<div class="eyebrow">${tag(s)}</div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}`;
export const sourceCard=id=>{const q=sources[id];return `<div class="source-card"><span class="source-id">${id}</span><div><p>${esc(q.author)}</p><a href="${q.url}" target="_blank" rel="noopener">${esc(q.title)} ↗</a><p class="source-detail">${esc(q.detail)}</p></div></div>`;};
function body(i,state){const s=scenes[i];switch(i){
case 0:return `<div class="hero-backdrop" aria-hidden="true"></div><div class="hero-copy">${heading(s,'Ein Leben<br>voller <em>Spaß?</em>')}<p class="lead">Jeden Tag spielen, Serien schauen und genießen – wäre das ein glückliches Leben?</p><div class="choices" aria-label="Lokale Einschätzung">${['Ja','Unsicher','Nein'].map((v,n)=>button(v,'vote',`data-value="${n}" aria-pressed="${state.vote===n}"`)).join('')}</div>${reveal(1,'<p class="insight">Was macht ein Leben <strong>glücklich?</strong></p>')}<p class="small">Handzeichen genügen. Keine richtige oder falsche Startantwort.</p></div><div class="hero-art">${pose(3,'student','Erfundener Schüler mit Gamecontroller')}${pose(0,'philosopher','Nachdenkender Philosoph')}</div>${caption('Abb. 1: Genuss trifft Nachdenken. Eigene KI-Illustrationen N1; Hintergrund N3.')}`;
case 1:return `${heading(s,'Sechs Aufgaben.<br><em>Eine große Frage.</em>')}<div class="agenda">${tasks.map((t,n)=>button(`<span class="station-number">0${n+1}</span><span>${t}</span><span class="station-arrow">↗</span>`,'jump',`class="station" data-index="${taskScenes[n]}"`)).join('')}</div><p class="insight agenda-note">Was macht ein Leben glücklich?</p>${caption('Aufgaben 1–6 nach Q1 · S. 2. Die Aufgaben stehen außerhalb der Textzeilenzählung.')}`;
case 2:return `${heading(s,'Ein Denker.<br><em>Viele Fragen.</em>')}<div class="timeline">${[['384 v. Chr.','Stagira','Geburt'],['ab 367','Athen','Platons Akademie'],['ab 343/342','Makedonien','Lehrer Alexanders'],['um 335','Athen','Das Lykeion'],['322 v. Chr.','Chalkis','Tod']].map(x=>`<div><span class="timeline-point"></span><b>${x[0]}</b><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div>${reveal(1,`<div class="works">${[['Nikomachische Ethik','Was macht ein gutes Leben aus?'],['Politik','Wie gestalten wir Gemeinschaft?'],['Über die Seele','Welche Fähigkeiten haben Lebewesen?'],['Metaphysik','Was ist das Seiende – und was sind seine Ursachen?']].map(x=>`<div><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`)}<p class="section-note">384–322 v. Chr. · Philosoph, Forscher, Lehrer</p>`;
case 3:return `${heading(s,'Seele heißt:<br><em>Fähigkeiten des Lebens.</em>')}<div class="soul-diagram" role="group" aria-label="Vereinfachtes Seelenschema nach NE I.13"><svg class="soul-lines" viewBox="0 0 1000 270" preserveAspectRatio="none" aria-hidden="true"><path d="M500 42V75H265V100 M500 75H790V100"/><path class="reveal" data-reveal="1" d="M265 130V168H125V193 M265 168H410V193 M790 130V193"/><path class="listening reveal" data-reveal="2" d="M755 239H565"/></svg><div class="soul-root">Seele</div><div class="soul-level"><div>Unvernünftig</div><div>Vernünftig</div></div><div class="soul-abilities reveal" data-reveal="1"><div class="soul-node ${state.example===0?'highlight':''}"><h3>Vegetativ</h3><p>Ernährung & Wachstum</p><small>ohne Vernunft</small></div><div class="soul-node ${state.example===1?'highlight':''}"><h3>Begehrend</h3><p>Wünsche & Gefühle</p><small class="reveal" data-reveal="2">kann auf Vernunft hören</small></div><div class="soul-node ${state.example===2?'highlight':''}"><h3>Vernünftig</h3><p>Denken & Urteilen</p><small>abwägen und entscheiden</small></div></div></div>${reveal(2,`<div class="example-row"><span>Zum Beispiel:</span>${button('Verdauen & wachsen','example','data-value="0"')}${button('Essen wollen','example','data-value="1"')}${button('Fair teilen','example','data-value="2"')}</div>`)}${caption('Abb. 4: Vereinfachte ethische Unterscheidung, eigene Darstellung nach Q3 · I.13. Keine Anatomie und keine vollständige Seelenlehre.')}`;
case 4:return `${heading(s,'<em>Eudaimonia.</em>','Ein gelungenes Leben – über seine ganze Dauer.')}<div class="virtues"><div><span class="overline">CHARAKTERTUGENDEN</span><h2>Gut handeln.</h2><p>Wünsche, Gefühle und Handlungen angemessen ausrichten.</p><span class="examples">Mut · Gerechtigkeit</span></div><div class="virtue-join" aria-hidden="true">&</div><div><span class="overline">VERSTANDESTUGENDEN</span><h2>Gut denken.</h2><p>Praktisch entscheiden und grundlegende Zusammenhänge erkennen.</p><span class="examples">Klugheit · Weisheit</span></div></div>${reveal(1,quote(0))}`;
case 5:{const chosen=state.mesotes;return `${heading(s,'Mut hat ein <em>Maß.</em>','Eine Person wird gemobbt. Wie reagieren wir?')}<div class="mesotes-stage">${mesotes.map((m,n)=>`<button type="button" class="reaction ${n===chosen?'selected':''}" data-action="mesotes" data-value="${n}" aria-pressed="${n===chosen}"><span class="reaction-tag">${m.tag}</span><span class="reaction-art" role="img" aria-label="${esc(m.text)}" style="--reaction-x:${n*50}%"></span><strong>${m.title}</strong><span>${m.text}</span></button>`).join('')}</div>${reveal(1,`<p class="mesotes-explanation">${mesotes[chosen].detail}</p>`)}<p class="principle">Das angemessene Maß hängt von <strong>Person und Situation</strong> ab.</p>${caption('Abb. 6: Drei Reaktionen auf Mobbing. Eigene Gegenwartsübertragung; KI-Illustrationen N2. Keine mathematische Mitte.')}`;}
case 6:return `${heading(s,'Aus Handlungen<br>wird <em>Haltung.</em>')}<div class="habit-layout"><div class="habit-path">${[['01','Verstehen','Was ist in dieser Situation richtig?'],['02','Bewusst entscheiden','Das Richtige um seiner selbst willen tun.'],['03','Eine Haltung entwickeln','Durch wiederholtes angemessenes Handeln.']].map(x=>`<div><span>${x[0]}</span><section><h2>${x[1]}</h2><p>${x[2]}</p></section></div>`).join('')}</div>${pose(4,'habit-figure','Hilfsbereiter Schüler')}</div>${reveal(1,'<p class="principle">Übung <b>+</b> Einsicht <b>+</b> bewusste Wahl</p>')}${caption('Abb. 7: Hilfsbereitschaft als Beispiel für geübtes Handeln. Eigene KI-Illustration N1.')}`;
case 7:return `${heading(s,'Wofür <em>leben</em> wir?','Drei Lebensschwerpunkte – heutige Beispiele, eigene Übertragung.')}<div class="life-stage">${lives.map((l,n)=>`<button class="life ${n===state.life?'selected':''}" data-action="life" data-value="${n}" aria-pressed="${n===state.life}"><span class="life-number">0${n+1}</span>${pose(l.pose,'life-figure',l.title)}<h2>${l.title}</h2><strong>${l.purpose}</strong><p>${l.example}</p></button>`).join('')}</div>${caption('Abb. 8: Genuss, öffentliches Handeln, Betrachtung. KI-Illustrationen N1. Tätigkeiten können sich in einem Leben verbinden.')}`;
case 8:return `${heading(s,'Erkenntnis.<br><em>Um ihrer selbst willen.</em>','Theoria · aktive Betätigung theoretischer Einsicht')}<div class="theoria-layout">${pose(5,'theoria-figure','Schüler beschäftigt sich mit Erkenntnis')}<div class="theoria-arguments"><div><b>01</b><p>Sie verwirklicht das Beste im Menschen:<br><strong>die Vernunft.</strong></p></div>${reveal(1,'<div><b>02</b><p>Sie gilt als besonders<br><strong>beständig und erfreulich.</strong></p></div>')}${reveal(2,'<div><b>03</b><p>Sie ist vergleichsweise<br><strong>selbstgenügsam.</strong></p></div>')}</div></div><div class="foundation"><strong>Voraussetzungen: Versorgung & Muße</strong><span>Muße = freie Zeit für eine wertvolle Tätigkeit</span></div>${caption('Abb. 9: Betrachtung als Tätigkeit. KI-Illustration N1. Der Vorrang der Betrachtung ist Aristoteles’ Position.')}`;
case 9:return `${heading(s,'Glück ist etwas,<br>das wir <em>tun.</em>')}<div class="answer-chain">${[['Selbstzweck','Ein Ziel, das wir um seiner selbst willen wählen.'],['Tätig sein','Vernünftig und tugendgemäß leben.'],['Betrachtung','Im behandelten Text die höchste Tätigkeit.'],['Ein ganzes Leben','Mehr als ein kurzer schöner Moment.']].map((x,n)=>`<div><span>0${n+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>${reveal(1,quote(1))}`;
case 10:return `${heading(s,'Was <em>überzeugt</em> uns?','Unsere Bewertung · mögliche Stärken des Ideals')}<div class="debate-layout">${pose(1,'debate-figure','Philosoph zeigt auf die Argumente')}<div class="argument-list"><div><span>01</span><section><h2>Dauerhafter Sinn</h2><p>Wertvolle Tätigkeit statt nur schneller Belohnung.</p></section></div><div><span>02</span><section><h2>Mehr Unabhängigkeit</h2><p>Weniger Bindung an Beifall und ständigen Konsum.</p></section></div>${reveal(1,'<div><span>03</span><section><h2>Verantwortung für uns selbst</h2><p>Den eigenen Charakter durch Handeln entwickeln.</p></section></div>')}</div></div>${caption('Abb. 11: Argumente im Gespräch. Eigene KI-Illustration N1. Keine Garantie persönlicher Zufriedenheit.')}`;
case 11:return `${heading(s,'Wer kann <em>so leben?</em>','Unsere Kritik · Voraussetzungen und Grenzen')}<div class="critique-grid"><section><span>ZEIT & SICHERHEIT</span><h2>Muße ist<br>ungleich verteilt.</h2><p>Arbeit und Fürsorge lassen nicht allen dieselben Freiräume.</p></section><section><span>DIE RANGORDNUNG</span><h2>Warum Erkenntnis<br>über Fürsorge?</h2><p>Auch praktisches Engagement kann ein Leben prägen.</p></section><section><span>DIE ANTIKE HIERARCHIE</span><h2>Wen schließt<br>das Ideal aus?</h2><p>Den gesellschaftlichen Ausschluss übernehmen wir nicht.</p></section></div>${reveal(1,`<div class="critical-quote"><span class="critical-label">Historische Position · von uns kritisch beurteilt</span>${quote(2)}</div>`)}`;
case 12:return `<div class="hero-backdrop" aria-hidden="true"></div><div class="hero-copy">${heading(s,'Ein gutes Leben.<br><em>Was gehört dazu?</em>')}<p class="lead">Nachdenken und gutes Handeln sind überzeugende Leitideen.</p>${reveal(1,'<p class="insight">Eine einzige beste Lebensform für alle bleibt fraglich.</p><h2 class="closing-question">Was würdet ihr ergänzen?</h2>')}<p class="small">${state.vote!==null?'Eure Anfangsantwort: '+['Ja','Unsicher','Nein'][state.vote]+' · ':''}Raum für ein bis zwei kurze Antworten.</p></div><div class="hero-art">${pose(4,'student','Schüler fragt das Publikum')}${pose(0,'philosopher','Nachdenkender Philosoph')}</div>${caption('Abb. 13: Zurück zur Einstiegsfrage. Eigene Schlussbewertung; KI-Illustrationen N1 und N3.')}`;
case 13:return `${heading(s,'Gedanken brauchen<br><em>Quellen.</em>')}<div class="sources-grid">${['Q1','Q2','Q3','Q4'].map(sourceCard).join('')}</div><div class="source-notice"><a href="material/Aristoteles.pdf" target="_blank" rel="noopener">Originalarbeitsblatt ↗</a><a href="material/Aristoteles_Arbeitsblatt_mit_Zeilen.pdf" target="_blank" rel="noopener">Nummerierte Lesefassung ↗</a><p>Eigene feste Zeilenzählung: S. 1 = Z. 1–49, S. 2 = Z. 50–75. Überschrift und Aufgaben zählen nicht mit.</p></div>`;
case 14:return `${heading(s,'Zum <em>Nachlesen.</em>')}<div class="final-sources"><div>${['Q5','Q6'].map(sourceCard).join('')}<p class="source-detail">Quellen der Vorfassung: 15.09.2026.<br>Erneute Prüfung der Internetquellen: 21.09.2026.</p></div><div class="credits"><h2>Bilder & Schriften</h2><p><b>N1</b> Philosoph und Schüler, sechs Posen.<br><b>N2</b> Drei Reaktionen auf Mobbing.<br><b>N3</b> Griechischer Säulengang.</p><p>Eigene KI-Illustrationen, OpenAI ImageGen, 21.09.2026. Erklärbilder, keine historischen Originale.</p><p class="source-detail">Die im Prompt genannten B1–B4 lagen nicht als Dateien vor. N1–N3 sind ergänzte Ersatzillustrationen.</p><p><b>Cormorant Garamond & DM Sans</b><br>Lokal gebündelt · SIL Open Font License 1.1</p></div></div><p class="closing-mark">Das gute Leben beginnt mit einer guten Frage.</p>`;
}}
export function article(i,state){const s=scenes[i];const ranges=s.ranges.map(([a,b])=>`${a}–${b}`).join(', ');return `<article class="scene scene-${i+1} ${[0,12].includes(i)?'hero':''}" data-scene="${i}" aria-label="Szene ${i+1}: ${esc(s.title)}">${body(i,state)}<div class="scene-evidence"><span>${s.refs.map(id=>cite(id,id==='Q1'&&ranges?'Z. '+ranges:'')).join('')}</span><span class="evidence-detail">${s.task?'AUFGABE '+s.task+' · ':''}${s.id} / 15</span></div></article>`;}

